import sys

def can_partition(arr, target_sum):
    """Check if we can partition the array into groups where each group sums to target_sum"""
    current_sum = 0
    groups = 0

    for num in arr:
        if current_sum + num > target_sum:
            # Start a new group
            current_sum = num
            groups += 1
        else:
            current_sum += num

    # Check if we ended with exactly one group
    if current_sum == target_sum:
        return groups
    return -1

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    total_sum = sum(arr)

    # Find all possible values x and corresponding k
    results = {}

    for x in range(1, total_sum + 1):
        k = can_partition(arr, x)
        if k != -1:
            results[x] = k

    # Find the maximum k
    max_k = max(results.values())

    # Get all values that achieve max_k
    max_values = [x for x, k in results.items() if k == max_k]

    # Sort and print
    print(max_k)
    print(' '.join(map(str, sorted(max_values))))

if __name__ == "__main__":
    solve()
"}

