def foo_function(t, A, B, C, D):
    return A * t * t * t + B * t * t + C * t + D


def find_max_t(A, B, C, D, K):
    # Binary search for the maximum t where F(t) <= K
    low = 0
    high = 10**18  # Upper bound (since F(t) <= 10^18)

    while low < high:
        mid = (low + high + 1) // 2
        val = foo_function(mid, A, B, C, D)

        if val <= K:
            low = mid
        else:
            high = mid - 1

    return low

T = int(input())
for _ in range(T):
    A, B, C, D, K = map(int, input().split())
    print(find_max_t(A, B, C, D, K))
"}

