def reverse_directions(instructions):
    """Reverse a list of direction instructions."""
    reversed_instructions = []

    # Reverse the order of all instructions
    for i in range(len(instructions) - 1, -1, -1):
        instruction = instructions[i]

        # Flip direction if it's not the first instruction
        if i != len(instructions) - 1:
            if instruction.startswith("Left"):
                instruction = instruction.replace("Left", "Right")
            elif instruction.startswith("Right"):
                instruction = instruction.replace("Right", "Left")

        reversed_instructions.append(instruction)

    return reversed_instructions

T = int(input())
for _ in range(T):
    N = int(input())
    instructions = []

    for _ in range(N):
        line = input().strip()
        instructions.append(line)

    # Reverse the instructions
    reversed_instructions = reverse_directions(instructions)

    # Print the reversed instructions
    for instruction in reversed_instructions:
        print(instruction)

    # Print a blank line after each test case
    print()
