from collections import defaultdict, deque

def solve():
    # Read number of laptops
    n = int(input())

    # Read number of connections
    c = int(input())

    # Build graph
    graph = defaultdict(list)

    for _ in range(c):
        u, v = map(int, input().split())
        graph[u].append(v)
        graph[v].append(u)

    # Read number of queries
    q = int(input())

    for _ in range(q):
        source, dest = map(int, input().split())

        # Check if there's a direct connection
        if dest in graph[source]:
            print("Direct Connection")
        else:
            # Check if there's an indirect connection using BFS
            visited = set()
            queue = deque([source])
            visited.add(source)

            found = False
            while queue:
                node = queue.popleft()
                if node == dest:
                    found = True
                    break
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)

            if found:
                print("Indirect Connection")
            else:
                print("No Connection")

if __name__ == "__main__":
    solve()
