import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    T = int(data[0])
    out_lines = []

    for i in range(1, T + 1):
        N = int(data[1 + 2 * (i - 1)])
        M = int(data[2 + 2 * (i - 1)])

        if M >= N:
            out_lines.append("0.00")
        else:
            # E[k] = 2^(N+1) - 2^(k+1)
            result = 2 ** (N + 1) - 2 ** (M + 1)
            out_lines.append(f"{result:.2f}")

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

