import sys

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        # Check if this is the end of input
        if line == '0':
            break

        # Parse the line
        parts = list(map(int, line.split()))
        if len(parts) == 0:
            continue

        N = parts[0]

        max_volume = 0

        for _ in range(N):
            # Read the next line for this planet
            while True:
                line = sys.stdin.readline()
                if not line:
                    break
                line = line.strip()
                if line:
                    break

            if not line:
                break

            planet_parts = list(map(int, line.split()))
            if len(planet_parts) < 3:
                continue

            di, ti, *volumes = planet_parts
            max_volume = max(max_volume, max(volumes))

        print(max_volume)

if __name__ == "__main__":
    main()
