n, q = map(int, input().split())

# Track busy servers at each time
busy = set()

for _ in range(q):
    ti, ki, di = map(int, input().split())

    # Find unoccupied servers
    unoccupied = []
    for server in range(1, n + 1):
        if server not in busy:
            unoccupied.append(server)

    if len(unoccupied) >= ki:
        # Assign the ki smallest unoccupied servers
        assigned = unoccupied[:ki]

        # Mark them as busy from ti to ti + di - 1
        for server in assigned:
            for t in range(ti, ti + di):
                busy.add(server)

        # Output the sum of assigned server IDs
        print(sum(assigned))
    else:
        print(-1)
"}

