{"code": "
while True:
    n, m = map(int, input().split())
    if n == 0 and m == 0:
        break

    # Initialize count array
    counts = [0] * m

    for _ in range(n):
        preferences = list(map(int, input().split()))
        for i in range(m):
            if preferences[i] == 1:
                counts[i] += 1

    # Sort by count (descending), then by location number (ascending)
    sorted_locations = sorted(range(m), key=lambda x: (-counts[x], x))

    # Output
    print(' '.join(str(loc + 1) for loc in sorted_locations))
"}

