def count_le(x, ranges):
    """Count how many distinct numbers ≤ x exist in all ranges."""
    count = 0
    for A, B in ranges:
        if B < x:
            count += B - A + 1
        elif A <= x:
            count += x - A + 1
    return count

def find_kth_kth_smallest(K, ranges):
    """Find the Kth smallest number in the sequence."""
    # Binary search bounds
    left = -10**18
    right = 10**18

    # Find the smallest x such that count_le(x) >= K
    while left < right:
        mid = (left + right) // 2
        if count_le(mid, ranges) >= K:
            right = mid
        else:
            left = mid + 1

    # Check if Kth smallest exists
    if count_le(left, ranges) >= K:
        return left
    else:
        return -1

T = int(input())
for _ in range(T):
    N, Q = map(int, input().split())
    ranges = []
    for _ in range(N):
        A, B = map(int, input().split())
        ranges.append((A, B))

    for _ in range(Q):
        K = int(input())
        print(find_kth_kth_smallest(K, ranges))
